import{Z as e,e as a,f as n,a0 as o}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"PayPal","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/paypal.md","filePath":"integrations/payments/paypal.md","lastUpdated":1780377007000}'),i={name:"integrations/payments/paypal.md"};function r(s,t,l,p,h,c){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="paypal" tabindex="-1">PayPal <a class="header-anchor" href="#paypal" aria-label="Permalink to &quot;PayPal&quot;">​</a></h1><p>Connect PayPal to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>PayPal</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-paypal-api" tabindex="-1">Step 2. Connect to the PayPal API <a class="header-anchor" href="#step-2-connect-to-the-paypal-api" aria-label="Permalink to &quot;Step 2. Connect to the PayPal API&quot;">​</a></h3><ol><li>Go to your <a href="https://developer.paypal.com/developer/applications/" target="_blank">PayPal REST API</a> application settings.</li><li>Select either <strong>Sandbox</strong> or <strong>Live</strong> and click the <strong>Create App</strong> button.</li><li>Enter a <strong>App Name</strong> and select <strong>Merchant</strong> for the <strong>App Type</strong>.</li><li>Copy the <strong>Client ID</strong> from PayPal and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Secret</strong> from PayPal and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select PayPal for the <strong>Payment Provider</strong>.</li></ol><p>The PayPal payment integration supports only once-off payments.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',14)])])}const f=e(i,[["render",r]]);export{g as __pageData,f as default};
